"""Readable reports and consumer ports from the frozen, manually reviewed contracts."""
import csv, datetime, hashlib, json, xml.etree.ElementTree as E
from pathlib import Path
R = Path(__file__).resolve().parent

def read(name):
    return json.loads((R / name).read_text())

def write(name, x):
    (R / name).write_text(json.dumps(x, ensure_ascii=False, indent=2) + '\n')

def mdcell(s):
    return str(s).replace('|', '/').replace('\n', ' ')

def link(o):
    return o['source'].get('url')
obs = read('VERIFIED_OBSERVATIONS.json')
audit = read('SOURCE_ADMISSION.json')
result = read('results.json')
labels = {'CROWN-MARGIN-WALL': "The crown's margin, gap and wall", 'TOOTH-FORCE-CLOSED-BITE': 'Bite power and observation at closed bite', 'GUIDE-ACCURACY': 'Guidenoggrannhet', 'PULPOTOMY-CONVERSION': 'Pulpotomy and transition to root treatment', 'MILLING-DEFLECTION': 'Milling deflection', 'CONTRALATERAL-SYMMETRY': 'Kontralateral symmetri'}
summaries = {'CROWN-MARGIN-WALL': "Six incorrect identities have been fixed in the audit file. McLean , Dedmon and Holmes had PMID pointing to second substances. Holmes defines different types of misfit; it does not give any numerical limit of measurement errors. McLeans often quoted 120 µm is here secondaryly coated and does not receive a new universal tolerance value. Elbadawy applies to occlusal veneer and Zheng endokronas. Dauti and Sarhan get correct DOI / PMID .\n\nThe regional , before cementing measured columns contained in Table 2 of 41337508 are retained per region. The label task for zirconia is inconsistent in the article's abstract/Table 1 . Kale indicates the internal CAD -spacer 30 / 40 / 50 µm and measured vertical margin 85 / 68 / 53 µm ; abstracts conclusion goes in the opposite direction. Dauti measures another material family and another margin. No joint team of sparse teams have been selected.\n\nKATANA : s custom charts indicate ML / HT 0,4 / 0,5 mm for anteriors/postior and UTML / STML 0,8 / 1,0 mm . The diagram does not specify any 0,5 mm debt width. Ivoclars 1 mm - leaf applies to the specified adhesion, dental-supported regime and excludes inter alia implant chandeliers/bruxism. These two documents are added as specifications, outside the 20 named harvest records.", 'TOOTH-FORCE-CLOSED-BITE': "Yoshikawa Table 3 : 443,7 N belongs to 107 women with prosthesis; 818,6 N belongs to 179 women without prosthesis. The difference between the group media is 374,9 N and the ratio 1,8449 . The teams are not paired. It corrects The swarm's population, without measuring an individual tooth's intervention response.\n\nVan Vuuren and S2 / S3 measure maximum force with inter-positioned apparatus. Waltimo has 14 mm jaw opening and several teeth against the house. These protocols cannot reject a 11,4 – 11,9 N height change response in simultaneous contact. The swarm's comparison T1 / T2 is therefore withdrawn. van Vuuren is only read through indexed primary PDF ; direct access gave 403 .\n\nS5 : s control group has printed regional means 14,3 + 50,1 + 43,9 = 108,3 %. They must not become a joint power partition by normalization. Hattori 2009 actually provides contact forces in N, but lacks the paired altitude intervention protocol. X94 already has Rubio's exact Table 1 ; abstractes roundings do not replace them.", 'GUIDE-ACCURACY': "The late delivered report is now reviewed: A1 – A20 , A3bis , B1 – B4 and C1 – C5 , and Wu as the recipient's existing source . Several missing numbers can be read in the primary sources: Tahmaseb's angle- KI , 2024's overview entrance columns and pilot profiles at Varga/Werny. Meta-KI and standard errors must not be used as individual SD. Nava Table 6 anger SE. A6 mixes individual studies with pooled result and error attributes Varga/Younes.\n\nC3 : s 0,136 is KI - lower boundary ; ICC estimate is 0,653 . Grunheid has different tables for repeatability and accuracy, as well as negative bis/ LOA that The swarm lost. MSE has units of mm^2. A15 : s text and tables give different KI ; both are recorded. A17 is an article from 2026. A18 : s GuideMia12 angle is 5,23 , and the correct PMCID is PMC12872909 .\n\nThe SMCD of the channel centre lines and an average cadaver distance do not identify any signed local channel wall boundary. A16 uses patient medication in its statistics; its SD must not become SD for implant. Primary browser reading is saved as clearly marked transcription when API full text is missing. Varga/Wu reproduces X87 : s 24 scale lines; eight retains INF . Ten new source scenarios use the same conditional operator, separately from the recipient's mandibulary population. No new physical nerve margin or signed drill shift has been identified.", 'PULPOTOMY-CONVERSION': "All 20 C references receive identity and quantity decisions. Output shares by treatment, diagnostic accuracy, animal data and intraoperative conversion are retained with separate denominators. Allihaibi's correct DOI is 10.1111/iej.14250; the alternative DOI of the harvest is rejected.\n\nLi: 3/47 senare rotbehandlingar efter trauma = 6,38 %, binomialt 95 % KI 1,34–17,54 %. It cannot be merged with Patels 25/86 intraoperative caries conversions = 29,07 %, KI 19,78 – 39,86 %. Li Table 2 anger PDL 2/4 respektive 1/43; Table 3 has reverse group headers and Table 4 contradicts operator/restaurant in Table 2. A forecast model/HR - calibration is blocked; table conflicts are preserved.\n\nPiecha Table 2 has the right cell orientation [[199,54 ],[204,143 ]], giving 253 / 600 the right with PR and 403 / 600 with PR + CBCT : exactly +25 percentage points. This is 600 reading-case pairs from 60 assessors and 10 cases, with the treatment dentist's fallout. They're clustered observations. The nominal iid-McNemar calculation is not robust uncertainty for a patient population. No conversion risk is derived. X88 : s existing, correctly delimited 25 / 86 - result does not change.", 'MILLING-DEFLECTION': "The late delivery report has now been reviewed. The swarm's k ∝ 1/d³ conflicts with its own beam model: k= 3 EI/L³ and I= π d⁴/64 provides k ∝ d⁴ at the same E,L. Double d gives exact factor 16 in rigidity; this is model algebra, not measured WC rigidity. S1 : s 0,8 D is the constitutive geometric cloud. S2 : s diameter is 802,2 µm , not 0,802 µm , and the four Test0 values are four fit methods on the same test.\n\nThe previously unread S7 original has been recovered. Mamedov/Layegh/Lazoglu,  DOI10.1016/j.procir.2013.06.080 , tryckta sidor  149 – 150 , reports laser-based tipping deflections X  −  38,99  to  39,34   µm  and Y  −  41  to  41,81   µm . Protocol: 1,5 mm two-cut WC tool, Al7050 , 20 000 rpm, cutting depth 300 µm , feeding 20 µm / tooth ; laser 1 mm from tip followed by extrapolation. The authors' force and deflection figures are not a tabulated, paired 1 N displacement test. The workpiece's E=71,7 GPa must not become the tool module. Source and deflection regimen are new; X89 : s power calibration remains UNKNOWN .\n\nRunout, flanking, cutting width, made PICN surface and crown columns are retained as various observed quantities. PMMA Table 1 provides regional process RMS 36,9 – 50,5 µm ; quotas against declared 20 µm scenario 1,845 – 2,525 . None of this isolates bending. X89 : s existing 150 / 256 conditional witnesses are not changed.", 'CONTRALATERAL-SYMMETRY': "Abduos 68,16 ± 23,33 µm is a labial regional agent on anterior teeth. Nagatas 275,5 ± 116,8 and 25,7 ± 13 µm are six cup points on manufactured and scanned type-odont chandeliers. Neither measures the entire the crown's surface-weighted P95. Nagata's time unit is actually printed as min and is kept without reinterpretation.\n\nOxilias 0,035 / 0,052 is in scaled Procrustes representation without specified physical mm device. Gurian verified accepted manuscripts have cross-sectional areas and a missing express area unit in Table 2 . Both are blocked for conversion to a physical crown shape limit.\n\nKlingenbergs angivna DOI 10.2307/2410360 avser svampmodeller. The actual Klingenberg/McIntyre article has DOI 10.1111/j.1558-5646.1998.tb02018.x. Taking shape is Wigley/Stillman/Craig-Atkins in Archaeometry, DOI 10.1111/arcm.12973. The authors /title of the Benítez post is corrected. These methodological references do not provide any new numerically full crown facit. PROOF_LANE : s 0 / 72 formwork pass and unknown clinical formwork limit retained."}
for (job, title) in labels.items():
    oo = [o for o in obs if o['job'] == job]
    aa = [a for a in audit if a['job'] == job]
    counts = result['source_jobs'][job]
    text = [f'# {title}\n', summaries[job], f"\nGranskade named entries: {len(aa)}. Without export numerical entry: {counts['no_numerical_bundle_export_items']}/{len(aa)} ({100 * counts['no_numerical_bundle_export_fraction']:.1f} %). Reasons are presented by post below. Exporterade observationsbuntar: {len(oo)}. Two manufacturer specifications are counted separately in the crown job.\n", '\nThe audit has separate gates for source support and transfer to the recipient. Each field carries the device, measurement resolution, statistical resolution and time edge of the JSONL draft.\n', '\n| ID and primary source | Quantity and printed values | Locator, population and protocol | Resolution / transfer |\n|---|---|---|---|']
    for o in oo:
        vals = '; '.join((f"{k}={json.dumps(v, ensure_ascii=False)} {o['value_metadata'][k]['unit']}" for (k, v) in o['values'].items()))
        source = f"[{o['id']}]({link(o)})"
        pop = f"{o['table_locator']}; {o['population']}; {o['protocol']}"
        status = f"{o['observation_resolution']}; {o['transfer_status']}: {o['transfer_reason']}"
        text.append('| ' + ' | '.join(map(mdcell, [source, vals, pop, status])) + ' |')
        if o['conflicts']:
            text.append('| 中 Source conflict | ' + mdcell('; '.join(o['conflicts'])) + ' | Preserved | PENDING_INDEPENDENT_REVIEW |')
    text += ['\n| Harvesting post | Verifierad identitet | Expiry and reason for refusal/limitation |\n|---|---|---|']
    for a in aa:
        url = 'https://doi.org/' + a['verified_doi'] if a['verified_doi'] else 'https://pubmed.ncbi.nlm.nih.gov/' + a['verified_pmid'] + '/' if a['verified_pmid'] else ''
        ident = f"[{a['verified_doi'] or 'PMID ' + a['verified_pmid']}]({url})" if url else 'See decisions and raw/CROSSREF_IDENTITY_CHECKS.json'
        text.append('| ' + ' | '.join(map(mdcell, [a['label'], ident, a['identity_status'] + ': ' + a['decision_reason']])) + ' |')
    consumers = sorted({c for o in oo for c in o['consumers']})
    text.append('\nMottagare: ' + ', '.join(consumers) + '. Precise impact and next measurement are in CONSUMER_IMPACTS.json.\n')
    text.append('Status: PENDING_INDEPENDENT_REVIEW. Hashaded original sources are available in sources/; an indexed PDF does not replace full text access.\n')
    (R / ('JOB_' + job + '.md')).write_text('\n'.join(text))
ports = []
for o in obs:
    for consumer in o['consumers']:
        for (key, value) in o['values'].items():
            ports.append({'source_id': o['id'], 'consumer': consumer, 'field': key, 'values': value, **o['value_metadata'][key], 'table_locator': o['table_locator'], 'source_locator': link(o), 'source_sha256': o['source_sha256'], 'claim_type': 'information_link', 'transfer_status': o['transfer_status'], 'transfer_reason': o['transfer_reason'], 'consumer_numeric_recalibration': 'BLOCKED_NO_MATCHED_PHYSICAL_OBSERVABLE', 'review_state': 'PENDING_INDEPENDENT_REVIEW'})
write('CONSUMER_PORTS.json', ports)
with (R / 'FACIT.csv').open('w', newline='') as f:
    cols = ['id', 'job', 'field', 'values', 'unit', 'observation_resolution', 'statistic_resolution', 'time_scale', 'source_locator', 'table_locator', 'population', 'protocol', 'transfer_status']
    w = csv.DictWriter(f, fieldnames=cols)
    w.writeheader()
    for o in obs:
        for (key, value) in o['values'].items():
            w.writerow({'id': o['id'], 'job': o['job'], 'field': key, 'values': json.dumps(value), **{k: o['value_metadata'][key][k] for k in ['unit', 'observation_resolution', 'statistic_resolution', 'time_scale']}, 'source_locator': link(o), **{k: o[k] for k in ['table_locator', 'population', 'protocol', 'transfer_status']}})
licenses = []
for p in sorted((R / 'sources').glob('PMC*.xml')):
    root = E.parse(p).getroot()
    ls = root.findall('.//permissions/license')
    licenses.append({'file': str(p.relative_to(R)), 'license_type': [l.get('license-type') for l in ls], 'license_locator': [a.get('{http://www.w3.org/1999/xlink}href') for l in ls for a in l.findall('.//ext-link')], 'license_text_in_original': [' '.join(''.join(l.itertext()).split()) for l in ls], 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()})
licenses += [{'file': 'sources/gurian2024.pdf', 'license_type': ['CC BY 4.0 per Newcastle repository record'], 'license_locator': ['https://eprints.ncl.ac.uk/295487']}, {'file': 'sources/KATANA_technical.pdf', 'license_type': ['Manufacturer document; redistribution permission not established'], 'license_locator': ['https://www.kuraraynoritake.com/world/product/cad_materials/pdf/katana_zircinia_technical_guide.pdf']}, {'file': 'sources/Ivoclar_adhesive1mm.pdf', 'license_type': ['Manufacturer document; redistribution permission not established'], 'license_locator': ['https://www.ivoclar.com/medias/sys_master/celum-connect2-assets/celum-connect2-assets/h95/h71/10112665124894/IPS-emax-CAD-Press-Adhesive-1mm-Crown.pdf']}, {'file': 'sources/metadata_*.json', 'license_type': ['Bibliographic metadata and abstracts retrieved from Europe PMC; no blanket fulltext license inferred'], 'license_locator': ['https://europepmc.org/']}]
licenses += [{'file': 'sources/Mamedov2013.pdf', 'license_type': ['CC BY-NC-ND per original publisher PDF;original preserved'], 'license_locator': ['https://doi.org/10.1016/j.procir.2013.06.080']}, {'file': 'sources/Grunheid2014.pdf', 'license_type': ['Publisher copyright;redistribution permission not established'], 'license_locator': ['https://doi.org/10.1016/j.ajodo.2013.10.012']}, {'file': 'sources/*_primary_browser_notes.json and *_primary_index_notes.json', 'license_type': ['Our limited factual reading notes;not original publisher fulltexts'], 'license_locator': ['External primary article URLs recorded inside each note']}]
write('SOURCE_LICENSES.json', licenses)
write('raw/REPORT_GENERATION.json', {'observation_bundles': len(obs), 'source_items': len(audit), 'field_rows': result['numerical_field_contract_count'], 'consumer_field_ports': len(ports), 'report_jobs': 6})
print('Wrote six job reports, FACIT.csv and', len(ports), 'typed consumer ports.')
